/** 
 * Called when a component calls  {@link android.content.Context#startService(Intent)}. <p>The default implementation handles the incoming media button events. In this case, the intent will have the action  {@link Intent#ACTION_MEDIA_BUTTON}. Override this method if this service also needs to handle actions other than  {@link Intent#ACTION_MEDIA_BUTTON}.
 */
@CallSuper @Override public int onStartCommand(@Nullable Intent intent,int flags,int startId){
  if (intent == null) {
    return START_STICKY;
  }
  if (Intent.ACTION_MEDIA_BUTTON.equals(intent.getAction())) {
    @Nullable Uri uri=intent.getData();
    @Nullable MediaSession session=uri != null ? MediaSession.getSession(uri) : null;
    if (session == null) {
      ControllerInfo controllerInfo=ControllerInfo.createLegacyControllerInfo();
      session=onGetSession(controllerInfo);
      if (session == null) {
        return START_STICKY;
      }
      try {
        addSession(session);
      } catch (UnsupportedOperationException | IllegalArgumentException | ClassCastException | NullPointerException e) {
        return START_STICKY;
      }
    }
    KeyEvent keyEvent=intent.getParcelableExtra(Intent.EXTRA_KEY_EVENT);
    if (keyEvent != null) {
      session.getSessionCompat().getController().dispatchMediaButtonEvent(keyEvent);
    }
  }
  return START_STICKY;
}
